export {
  CompletedFocusTab,
  create,
  FocusedTab,
  FocusTab,
  init,
  initialize,
  Message,
  Model,
  OutMessage,
  Selected,
  SelectedTab,
} from "../../../foldkit/ui/tabs";
export type {
  ActivationMode,
  InitConfig,
  InitReturn,
  Orientation,
  RenderInfo,
  TabInfo,
  UpdateReturn,
  ViewInputs,
} from "../../../foldkit/ui/tabs";

export {
  baseUiTabsListClasses,
  baseUiTabsPanelClasses,
  baseUiTabsRootClasses,
  baseUiTabsTabClasses,
  baseUiTabsVerticalListClasses,
  baseUiTabsVerticalRootClasses,
  baseUiTabsView,
} from "./view";
export type { BaseUiTabsViewInput } from "./view";

export {
  panelClasses as baseUiTabsPanelClasses,
  tabClasses as baseUiTabsTabClasses,
  tabListClasses as baseUiTabsListClasses,
  tabsRootClasses as baseUiTabsRootClasses,
  tabsView as baseUiTabsView,
  verticalTabListClasses as baseUiTabsVerticalListClasses,
  verticalTabsRootClasses as baseUiTabsVerticalRootClasses,
} from "../../../foldkit/ui/tabs/view";
export type { TabsViewInput as BaseUiTabsViewInput } from "../../../foldkit/ui/tabs/view";

import { describe, expect, test } from "vitest";

import * as Tabs from "./index";

describe("Base UI Tabs registry view", () => {
  test("reuses the Foldkit Tabs functional contract", () => {
    expect(Tabs.init).toBeTypeOf("function");
    expect(Tabs.create).toBeTypeOf("function");
    expect(Tabs.baseUiTabsView).toBeTypeOf("function");
    expect(Tabs.baseUiTabsTabClasses).toContain("data-[selected]");
  });
});
